#include <cassert>
#include <cstdint>
#include <limits>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
static_assert(std::numeric_limits<int>::digits <= 31,
              "This example requires int no wider than 32 bits.");
struct Selection { bool valid; int index; };
enum class Edge { Clamp, Wrap };
Selection Move(int index, int count, int delta, Edge edge) {
    if (count <= 0 || index < 0 || index >= count)
        return {false, index};
    const std::int64_t next = static_cast<std::int64_t>(index) + delta;
    if (edge == Edge::Wrap) {
        const std::int64_t normalized = ((next % count) + count) % count;
        return {true, static_cast<int>(normalized)};
    }
    const std::int64_t bounded = next < 0 ? 0 :
        (next >= count ? count - 1 : next);
    return {true, static_cast<int>(bounded)};
}
int main() {
    assert(!Move(0, 0, 1, Edge::Wrap).valid);
    assert(!Move(-1, 4, 1, Edge::Clamp).valid);
    assert(!Move(4, 4, 1, Edge::Wrap).valid);
    assert(Move(0, 8, -1, Edge::Wrap).index == 7);
    assert(Move(7, 8, 1, Edge::Wrap).index == 0);
    assert(Move(0, 8, -1, Edge::Clamp).index == 0);
    assert(Move(7, 8, 1, Edge::Clamp).index == 7);
    assert(Move(0, 1, std::numeric_limits<int>::min(), Edge::Wrap).index == 0);
    assert(Move(1, 3, std::numeric_limits<int>::max(), Edge::Clamp).index == 2);
    for (int count = 1; count <= 20; ++count)
      for (int index = 0; index < count; ++index)
        for (int delta = -50; delta <= 50; ++delta) {
            const Selection a = Move(index,count,delta,Edge::Wrap);
            const Selection b = Move(index,count,delta,Edge::Clamp);
            assert(a.valid && a.index >= 0 && a.index < count);
            assert(b.valid && b.index >= 0 && b.index < count);
            assert(Move(a.index,count,-delta,Edge::Wrap).index == index);
            assert(Move(index,count,0,Edge::Clamp).index == index);
        }
}
